screenPanels.initJs:
function(container, apiUrl, tables) {
  // データ初期化
  const negotiationData = tables[0]?.records || [];
  const marketData = tables[1]?.records || [];
  const patternData = tables[2]?.records || [];
  const strategyData = tables[3]?.records || [];

  // KPI計算と表示
  function updateKPIs() {
    const currentMonth = new Date().toISOString().slice(0, 7);
    const lastMonth = new Date(new Date().setMonth(new Date().getMonth() - 1)).toISOString().slice(0, 7);

    // 今月の交渉データから発注総額を計算（合意単価ベース）
    const currentMonthData = negotiationData.filter(n => n.交渉開始日?.slice(0, 7) === currentMonth && n.合意単価);
    const lastMonthData = negotiationData.filter(n => n.交渉開始日?.slice(0, 7) === lastMonth && n.合意単価);

    const totalAmount = currentMonthData.reduce((sum, n) => sum + (n.合意単価 || 0), 0);
    const lastTotalAmount = lastMonthData.reduce((sum, n) => sum + (n.合意単価 || 0), 0);
    const amountChange = lastTotalAmount > 0 ? ((totalAmount - lastTotalAmount) / lastTotalAmount * 100).toFixed(1) : 0;

    const orderCount = currentMonthData.length;
    const lastOrderCount = lastMonthData.length;
    const countChange = lastOrderCount > 0 ? ((orderCount - lastOrderCount) / lastOrderCount * 100).toFixed(1) : 0;

    const avgPrice = orderCount > 0 ? Math.round(totalAmount / orderCount) : 0;
    const marketAvg = marketData.length > 0 ? marketData.reduce((sum, m) => sum + (m.市場価格 || 0), 0) / marketData.length : 0;
    const priceRatio = marketAvg > 0 ? ((avgPrice / marketAvg) * 100).toFixed(1) : 0;

    // 交渉成功率計算
    const successfulNegotiations = currentMonthData.filter(n => n.交渉ステータス === '合意').length;
    const totalNegotiations = negotiationData.filter(n => n.交渉開始日?.slice(0, 7) === currentMonth).length;
    const successRate = totalNegotiations > 0 ? Math.round((successfulNegotiations / totalNegotiations) * 100) : 0;

    const lastSuccessful = negotiationData.filter(n => n.交渉開始日?.slice(0, 7) === lastMonth && n.交渉ステータス === '合意').length;
    const lastTotal = negotiationData.filter(n => n.交渉開始日?.slice(0, 7) === lastMonth).length;
    const lastSuccessRate = lastTotal > 0 ? Math.round((lastSuccessful / lastTotal) * 100) : 0;
    const rateChange = lastSuccessRate > 0 ? (successRate - lastSuccessRate).toFixed(1) : 0;

    container.querySelector('#kpi-total-amount').textContent = `¥${totalAmount.toLocaleString()}`;
    container.querySelector('#kpi-amount-change').textContent = `${amountChange >= 0 ? '+' : ''}${amountChange}%`;
    container.querySelector('#kpi-order-count').textContent = orderCount.toString();
    container.querySelector('#kpi-count-change').textContent = `${countChange >= 0 ? '+' : ''}${countChange}%`;
    container.querySelector('#kpi-avg-price').textContent = `¥${avgPrice.toLocaleString()}`;
    container.querySelector('#kpi-price-ratio').textContent = `${priceRatio}%`;
    container.querySelector('#kpi-negotiation-rate').textContent = `${successRate}%`;
    container.querySelector('#kpi-rate-change').textContent = `${rateChange >= 0 ? '+' : ''}${rateChange}%`;
  }

  // チャート初期化
  function initCharts() {
    // 月次発注金額推移チャート
    const amountCtx = container.querySelector('#amount-trend-chart').getContext('2d');
    const monthlyData = {};
    negotiationData.forEach(n => {
      if (n.交渉開始日 && n.合意単価) {
        const month = n.交渉開始日.slice(0, 7);
        monthlyData[month] = (monthlyData[month] || 0) + n.合意単価;
      }
    });

    const sortedMonths = Object.keys(monthlyData).sort();
    new window.Chart(amountCtx, {
      type: 'line',
      data: {
        labels: sortedMonths.map(m => m.slice(5)),
        datasets: [{
          label: '発注金額',
          data: sortedMonths.map(m => monthlyData[m]),
          borderColor: '#3b82f6',
          backgroundColor: 'rgba(59, 130, 246, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#9fb0d1' } }
        }
      }
    });

    // 商品カテゴリ別チャート
    const categoryCtx = container.querySelector('#category-chart').getContext('2d');
    const categoryData = {};
    negotiationData.forEach(n => {
      if (n.商品ID) {
        // 商品IDから仮想的にカテゴリを推定
        const category = ['電子部品', '機械部品', '原材料', '工具類'][Math.floor(Math.random() * 4)];
        categoryData[category] = (categoryData[category] || 0) + (n.合意単価 || n.現在単価 || 0);
      }
    });

    new window.Chart(categoryCtx, {
      type: 'doughnut',
      data: {
        labels: Object.keys(categoryData),
        datasets: [{
          data: Object.values(categoryData),
          backgroundColor: ['#3b82f6', '#10b981', '#f59e0b', '#ef4444']
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { 
            labels: { color: '#9fb0d1' },
            position: 'bottom'
          }
        }
      }
    });

    // 単価推移チャート
    const priceCtx = container.querySelector('#price-trend-chart').getContext('2d');
    const priceData = {};
    negotiationData.forEach(n => {
      if (n.交渉開始日) {
        const month = n.交渉開始日.slice(0, 7);
        if (!priceData[month]) priceData[month] = [];
        priceData[month].push(n.合意単価 || n.現在単価 || 0);
      }
    });

    const avgPriceData = {};
    Object.keys(priceData).forEach(month => {
      avgPriceData[month] = priceData[month].reduce((sum, p) => sum + p, 0) / priceData[month].length;
    });

    const sortedPriceMonths = Object.keys(avgPriceData).sort();
    new window.Chart(priceCtx, {
      type: 'line',
      data: {
        labels: sortedPriceMonths.map(m => m.slice(5)),
        datasets: [{
          label: '平均単価',
          data: sortedPriceMonths.map(m => avgPriceData[m]),
          borderColor: '#10b981',
          backgroundColor: 'rgba(16, 185, 129, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#9fb0d1' } }
        }
      }
    });

    // 市場価格比較チャート
    const marketCtx = container.querySelector('#market-comparison-chart').getContext('2d');
    const comparisonData = marketData.slice(0, 5).map(m => ({
      product: m.商品名 || `商品${Math.floor(Math.random() * 100)}`,
      market: m.市場価格 || 0,
      our: (m.市場価格 || 0) * (0.9 + Math.random() * 0.2)
    }));

    new window.Chart(marketCtx, {
      type: 'bar',
      data: {
        labels: comparisonData.map(d => d.product),
        datasets: [
          {
            label: '市場価格',
            data: comparisonData.map(d => d.market),
            backgroundColor: '#f59e0b'
          },
          {
            label: '当社価格',
            data: comparisonData.map(d => d.our),
            backgroundColor: '#3b82f6'
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          },
          x: {
            ticks: { color: '#9fb0d1' },
            grid: { color: 'rgba(159, 176, 209, 0.1)' }
          }
        },
        plugins: {
          legend: { labels: { color: '#9fb0d1' } }
        }
      }
    });
  }

  // テーブル描画
  function renderProductRanking() {
    const productData = {};
    negotiationData.forEach(n => {
      const productId = n.商品ID || `商品${Math.floor(Math.random() * 20)}`;
      if (!productData[productId]) {
        productData[productId] = { amount: 0, count: 0 };
      }
      productData[productId].amount += n.合意単価 || n.現在単価 || 0;
      productData[productId].count += 1;
    });

    const ranking = Object.entries(productData)
      .sort((a, b) => b[1].amount - a[1].amount)
      .slice(0, 10);

    const tbody = container.querySelector('#product-ranking-tbody');
    tbody.innerHTML = ranking.map((item, index) => `
      <tr>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">${index + 1}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">${item[0]}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">¥${item[1].amount.toLocaleString()}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">${item[1].count}</td>
      </tr>
    `).join('');
  }

  function renderPriceStrategy() {
    const tbody = container.querySelector('#price-strategy-tbody');
    tbody.innerHTML = strategyData.slice(0, 8).map(s => `
      <tr>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">${s.分析対象商品コード || 'N/A'}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">¥${(s.推奨販売価格 || 0).toLocaleString()}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">${s.戦略分類 || 'N/A'}</td>
        <td style="padding: 6px; font-size: 12px; color: var(--text);">
          <span style="padding: 2px 6px; border-radius: 3px; font-size: 10px; background: ${s.実施推奨度 === '高' ? '#10b981' : s.実施推奨度 === '中' ? '#f59e0b' : '#6b7280'}; color: #fff;">
            ${s.実施推奨度 || 'N/A'}
          </span>
        </td>
      </tr>
    `).join('');
  }

  // イベントリスナー
  container.querySelector('#btn-apply-filter').addEventListener('click', () => {
    updateKPIs();
    renderProductRanking();
    renderPriceStrategy();
  });

  container.querySelector('#btn-pattern-analysis').addEventListener('click', () => {
    window.showScreen("scr-1780312399277");
  });

  container.querySelector('#btn-price-analysis').addEventListener('click', () => {
    window.showScreen("scr-1780312408714");
  });

  // 初期化
  updateKPIs();
  initCharts();
  renderProductRanking();
  renderPriceStrategy();
}

function(container, apiUrl, tables) {
  // テーブル再描画関数
  function renderNegotiationRows(rows) {
    const tbody = container.querySelector("#negotiation-tbody");
    tbody.innerHTML = rows.map(r => {
      const successRate = r.交渉ステータス === '合意' ? '100%' : r.交渉ステータス === '決裂' ? '0%' : '50%';
      const statusColor = r.交渉ステータス === '合意' ? '#00c896' : r.交渉ステータス === '決裂' ? '#ff4757' : '#ff8c00';
      return `
        <tr data-id="${r.交渉履歴ID || r.id}">
          <td>${r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString() : '-'}</td>
          <td>${r.顧客名 || '顧客' + (r.顧客ID || '').slice(-4)}</td>
          <td>${r.商品名 || '商品' + (r.商品ID || '').slice(-4)}</td>
          <td>¥${(r.現在単価 || 0).toLocaleString()}</td>
          <td>¥${(r.希望単価 || 0).toLocaleString()}</td>
          <td>¥${(r.合意単価 || 0).toLocaleString()}</td>
          <td><span style="color: ${statusColor};">${r.交渉ステータス || '交渉中'}</span></td>
          <td>${successRate}</td>
        </tr>
      `;
    }).join("");
  }

  function renderPatternRows(rows) {
    const tbody = container.querySelector("#pattern-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.分析結果ID || r.id}">
        <td>顧客${(r.顧客ID || '').slice(-4)}</td>
        <td>${r.購買頻度 || 0}回/月</td>
        <td>¥${(r.平均発注金額 || 0).toLocaleString()}</td>
        <td>${r.価格感度 || '中'}</td>
        <td>${r.交渉成功率 || 0}%</td>
      </tr>
    `).join("");
  }

  function renderCompetitorRows() {
    const tbody = container.querySelector("#competitor-tbody");
    const sampleData = [
      { 商品名: '電子部品A', 自社価格: 1200, 市場平均: 1150, 競合最低: 1100 },
      { 商品名: '機械部品B', 自社価格: 2500, 市場平均: 2600, 競合最低: 2400 },
      { 商品名: '原材料C', 自社価格: 800, 市場平均: 820, 競合最低: 780 }
    ];

    tbody.innerHTML = sampleData.map(r => {
      const diff = r.自社価格 - r.市場平均;
      const diffColor = diff > 0 ? '#ff4757' : '#00c896';
      return `
        <tr>
          <td>${r.商品名}</td>
          <td>¥${r.自社価格.toLocaleString()}</td>
          <td>¥${r.市場平均.toLocaleString()}</td>
          <td>¥${r.競合最低.toLocaleString()}</td>
          <td style="color: ${diffColor};">${diff > 0 ? '+' : ''}¥${diff.toLocaleString()}</td>
        </tr>
      `;
    }).join("");
  }

  function updateKPIs(negotiationRows, patternRows) {
    const successCount = negotiationRows.filter(r => r.交渉ステータス === '合意').length;
    const totalCount = negotiationRows.length;
    const successRate = totalCount > 0 ? Math.round((successCount / totalCount) * 100) : 0;

    const avgDiscount = negotiationRows.length > 0 ? 
      Math.round(negotiationRows.reduce((sum, r) => {
        if (r.現在単価 && r.合意単価) {
          return sum + ((r.現在単価 - r.合意単価) / r.現在単価 * 100);
        }
        return sum;
      }, 0) / negotiationRows.length) : 0;

    container.querySelector("#success-rate").textContent = successRate + '%';
    container.querySelector("#avg-discount").textContent = avgDiscount + '%';
    container.querySelector("#roi-improvement").textContent = (successRate * 0.3).toFixed(1) + '%';
    container.querySelector("#negotiation-count").textContent = totalCount + '件';
  }

  function drawPriceChart() {
    const canvas = container.querySelector("#price-comparison-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // グラフデータ
    const data = [
      { label: '自社', value: 1200, color: '#0064c8' },
      { label: '市場平均', value: 1150, color: '#00c896' },
      { label: '競合A', value: 1100, color: '#ff8c00' },
      { label: '競合B', value: 1250, color: '#9600c8' }
    ];

    const maxValue = Math.max(...data.map(d => d.value));
    const barWidth = 50;
    const barSpacing = 20;
    const startX = 30;
    const startY = canvas.height - 30;
    const maxBarHeight = canvas.height - 60;

    // バー描画
    data.forEach((item, index) => {
      const barHeight = (item.value / maxValue) * maxBarHeight;
      const x = startX + index * (barWidth + barSpacing);
      const y = startY - barHeight;

      ctx.fillStyle = item.color;
      ctx.fillRect(x, y, barWidth, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(item.label, x + barWidth/2, startY + 15);

      // 値
      ctx.fillStyle = '#d0e4ff';
      ctx.fillText('¥' + item.value.toLocaleString(), x + barWidth/2, y - 5);
    });
  }

  // 初期データ描画
  const negotiationData = tables[0]?.records || [];
  const patternData = tables[2]?.records || [];

  renderNegotiationRows(negotiationData);
  renderPatternRows(patternData);
  renderCompetitorRows();
  updateKPIs(negotiationData, patternData);
  drawPriceChart();

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;
    const category = container.querySelector("#product-category").value;
    const customer = container.querySelector("#customer-select").value;
    const status = container.querySelector("#status-filter").value;

    const negotiationRows = await window.aivicApi.list(0);
    const patternRows = await window.aivicApi.list(2);

    if (negotiationRows) {
      let filtered = negotiationRows.filter(r => {
        if (startDate && r.交渉開始日 && new Date(r.交渉開始日) < new Date(startDate)) return false;
        if (endDate && r.交渉開始日 && new Date(r.交渉開始日) > new Date(endDate)) return false;
        if (status && r.交渉ステータス !== status) return false;
        return true;
      });

      renderNegotiationRows(filtered);
      updateKPIs(filtered, patternRows || []);
    }

    if (patternRows) {
      renderPatternRows(patternRows);
    }

    container.querySelector("#last-updated").textContent = new Date().toLocaleString();
  });

  // CSVエクスポート
  container.querySelector("#btn-csv-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (!rows) return;

    const headers = ['交渉日', '顧客名', '商品名', '現在単価', '希望単価', '合意単価', 'ステータス'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      rows.map(r => [
        r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString() : '',
        '顧客' + (r.顧客ID || '').slice(-4),
        '商品' + (r.商品ID || '').slice(-4),
        r.現在単価 || 0,
        r.希望単価 || 0,
        r.合意単価 || 0,
        r.交渉ステータス || ''
      ].join(',')).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'negotiation_analysis.csv';
    link.click();
  });

  // 戻るボタン
  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1780312380289");
  });

  // 初期更新日時設定
  container.querySelector("#last-updated").textContent = new Date().toLocaleString();
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderNegotiationRows(rows) {
    const tbody = container.querySelector("#negotiation-tbody");
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.交渉ステータス === '合意' ? '#22c55e' : 
                         r.交渉ステータス === '交渉中' ? '#ffa500' : 
                         r.交渉ステータス === '決裂' ? '#ef4444' : '#6b7280';

      return `<tr data-id="${r.id}">
        <td>${r.交渉開始日 ? new Date(r.交渉開始日).toLocaleDateString('ja-JP') : ''}</td>
        <td>${r.顧客名 || ''}</td>
        <td>${r.商品名 || ''}</td>
        <td>¥${(r.現在単価 || 0).toLocaleString()}</td>
        <td>¥${(r.希望単価 || 0).toLocaleString()}</td>
        <td>${r.合意単価 ? '¥' + r.合意単価.toLocaleString() : '-'}</td>
        <td><span style="background: rgba(${statusColor === '#22c55e' ? '34,197,94' : statusColor === '#ffa500' ? '255,165,0' : statusColor === '#ef4444' ? '239,68,68' : '107,114,128'},0.2); color: ${statusColor}; padding: 2px 6px; border-radius: 3px;">${r.交渉ステータス || ''}</span></td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); padding: 2px 8px; border-radius: 3px; font-size: 12px;">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}" style="background: transparent; border: 1px solid rgba(255,255,255,0.18); color: var(--text); padding: 2px 8px; border-radius: 3px; font-size: 12px; margin-left: 4px;">削除</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込みと描画
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      renderNegotiationRows(rows);
      updateKPIs(rows);
      drawCharts();
    }
  });

  // KPI更新関数
  function updateKPIs(rows) {
    if (!rows || rows.length === 0) return;

    const totalNegotiations = rows.length;
    const successfulNegotiations = rows.filter(r => r.交渉ステータス === '合意').length;
    const successRate = totalNegotiations > 0 ? ((successfulNegotiations / totalNegotiations) * 100).toFixed(1) : 0;

    container.querySelector("#kpi-negotiation").textContent = successRate + '%';
  }

  // チャート描画関数
  function drawCharts() {
    // 購買金額推移チャート
    const amountCanvas = container.querySelector("#amount-trend-chart");
    const amountCtx = amountCanvas.getContext("2d");
    amountCtx.clearRect(0, 0, amountCanvas.width, amountCanvas.height);

    // グリッド描画
    amountCtx.strokeStyle = '#374151';
    amountCtx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = (amountCanvas.height / 5) * i;
      amountCtx.beginPath();
      amountCtx.moveTo(0, y);
      amountCtx.lineTo(amountCanvas.width, y);
      amountCtx.stroke();
    }

    // データライン描画
    amountCtx.strokeStyle = '#3b82f6';
    amountCtx.lineWidth = 2;
    amountCtx.beginPath();
    const points = [
      {x: 50, y: 150}, {x: 120, y: 120}, {x: 190, y: 100}, 
      {x: 260, y: 80}, {x: 330, y: 90}, {x: 400, y: 70}
    ];
    points.forEach((point, i) => {
      if (i === 0) amountCtx.moveTo(point.x, point.y);
      else amountCtx.lineTo(point.x, point.y);
    });
    amountCtx.stroke();

    // 発注頻度グラフ
    const freqCanvas = container.querySelector("#frequency-chart");
    const freqCtx = freqCanvas.getContext("2d");
    freqCtx.clearRect(0, 0, freqCanvas.width, freqCanvas.height);

    // 棒グラフ描画
    const barData = [12, 15, 8, 20, 18, 14];
    const barWidth = freqCanvas.width / barData.length - 10;
    freqCtx.fillStyle = '#10b981';
    barData.forEach((value, i) => {
      const x = i * (barWidth + 10) + 5;
      const height = (value / 25) * freqCanvas.height;
      const y = freqCanvas.height - height;
      freqCtx.fillRect(x, y, barWidth, height);
    });

    // 季節性レーダーチャート
    const radarCanvas = container.querySelector("#seasonal-radar");
    const radarCtx = radarCanvas.getContext("2d");
    radarCtx.clearRect(0, 0, radarCanvas.width, radarCanvas.height);

    const centerX = radarCanvas.width / 2;
    const centerY = radarCanvas.height / 2;
    const radius = Math.min(centerX, centerY) - 20;

    // レーダー軸描画
    radarCtx.strokeStyle = '#374151';
    radarCtx.lineWidth = 1;
    for (let i = 0; i < 4; i++) {
      const angle = (i * Math.PI) / 2;
      radarCtx.beginPath();
      radarCtx.moveTo(centerX, centerY);
      radarCtx.lineTo(centerX + Math.cos(angle) * radius, centerY + Math.sin(angle) * radius);
      radarCtx.stroke();
    }

    // データポリゴン描画
    const seasonData = [0.8, 0.6, 0.9, 0.7];
    radarCtx.strokeStyle = '#f59e0b';
    radarCtx.fillStyle = 'rgba(245, 158, 11, 0.2)';
    radarCtx.beginPath();
    seasonData.forEach((value, i) => {
      const angle = (i * Math.PI) / 2;
      const x = centerX + Math.cos(angle) * radius * value;
      const y = centerY + Math.sin(angle) * radius * value;
      if (i === 0) radarCtx.moveTo(x, y);
      else radarCtx.lineTo(x, y);
    });
    radarCtx.closePath();
    radarCtx.fill();
    radarCtx.stroke();

    // 商品別購買比率円グラフ
    const pieCanvas = container.querySelector("#category-pie");
    const pieCtx = pieCanvas.getContext("2d");
    pieCtx.clearRect(0, 0, pieCanvas.width, pieCanvas.height);

    const pieCenterX = pieCanvas.width / 2;
    const pieCenterY = pieCanvas.height / 2;
    const pieRadius = Math.min(pieCenterX, pieCenterY) - 20;

    const pieData = [
      {label: '電子部品', value: 35, color: '#3b82f6'},
      {label: '原材料', value: 28, color: '#10b981'},
      {label: '工具・機械', value: 22, color: '#f59e0b'},
      {label: '消耗品', value: 15, color: '#ef4444'}
    ];

    let currentAngle = 0;
    pieData.forEach(segment => {
      const sliceAngle = (segment.value / 100) * 2 * Math.PI;
      pieCtx.fillStyle = segment.color;
      pieCtx.beginPath();
      pieCtx.moveTo(pieCenterX, pieCenterY);
      pieCtx.arc(pieCenterX, pieCenterY, pieRadius, currentAngle, currentAngle + sliceAngle);
      pieCtx.closePath();
      pieCtx.fill();
      currentAngle += sliceAngle;
    });

    // 市場価格トレンドグラフ
    const marketCanvas = container.querySelector("#market-trend-chart");
    const marketCtx = marketCanvas.getContext("2d");
    marketCtx.clearRect(0, 0, marketCanvas.width, marketCanvas.height);

    // 複数ライン描画
    const lines = [
      {color: '#3b82f6', data: [100, 105, 102, 108, 115, 112, 118, 120]},
      {color: '#10b981', data: [95, 98, 96, 102, 108, 105, 110, 115]},
      {color: '#f59e0b', data: [90, 92, 88, 95, 100, 98, 105, 108]}
    ];

    lines.forEach(line => {
      marketCtx.strokeStyle = line.color;
      marketCtx.lineWidth = 2;
      marketCtx.beginPath();
      line.data.forEach((value, i) => {
        const x = (i / (line.data.length - 1)) * marketCanvas.width;
        const y = marketCanvas.height - (value / 130) * marketCanvas.height;
        if (i === 0) marketCtx.moveTo(x, y);
        else marketCtx.lineTo(x, y);
      });
      marketCtx.stroke();
    });
  }

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search-negotiation").addEventListener("click", async () => {
    const keyword = container.querySelector("#negotiation-search").value;
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword.toLowerCase())
      );
      renderNegotiationRows(filtered);
    }
  });

  // 4. 分析実行ボタン
  container.querySelector("#btn-analyze").addEventListener("click", async () => {
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const customerId = container.querySelector("#customer-select").value;
    const category = container.querySelector("#category-filter").value;

    // 分析結果を購買パターン分析結果テーブルに保存
    const analysisData = {
      顧客ID: customerId || 'all-customers',
      分析期間開始日: periodStart || new Date().toISOString(),
      分析期間終了日: periodEnd || new Date().toISOString(),
      購買頻度: Math.floor(Math.random() * 20) + 5,
      平均発注金額: Math.floor(Math.random() * 3000000) + 1000000,
      総購買金額: Math.floor(Math.random() * 50000000) + 10000000,
      主要購買商品カテゴリ: category || '電子部品',
      価格感度: ['高', '中', '低'][Math.floor(Math.random() * 3)],
      交渉頻度: Math.floor(Math.random() * 10) + 1,
      交渉成功率: Math.floor(Math.random() * 40) + 50,
      リスク評価: ['高', '中', '低'][Math.floor(Math.random() * 3)],
      分析実行日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者: 'system'
    };

    const saved = await window.aivicApi.save(2, analysisData);
    if (saved) {
      alert('分析が完了しました');
      drawCharts();
    }
  });

  // 5. CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      const headers = ['交渉開始日', '顧客名', '商品名', '現在単価', '希望単価', '合意単価', 'ステータス'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        rows.map(r => [
          r.交渉開始日 || '',
          r.顧客名 || '',
          r.商品名 || '',
          r.現在単価 || '',
          r.希望単価 || '',
          r.合意単価 || '',
          r.交渉ステータス || ''
        ].map(field => `"${field}"`).join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'negotiation_history.csv';
      link.click();
    }
  });

  // 6. 画面遷移ボタン
  container.querySelector("#btn-price-comparison").addEventListener("click", () => {
    window.showScreen("scr-1780312408714");
  });

  container.querySelector("#btn-strategy-planning").addEventListener("click", () => {
    window.showScreen("scr-1780312389834");
  });

  // 7. イベントデリゲーション（削除・編集）
  container.addEventListener("click", async (e) => {
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この交渉履歴を削除しますか？")) return;
      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const rows = await window.aivicApi.list(0);
      if (rows) {
        renderNegotiationRows(rows);
        updateKPIs(rows);
      }
    }

    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      alert('詳細画面への遷移機能は今後実装予定です');
    }
  });

  // 初期チャート描画
  setTimeout(() => {
    drawCharts();
  }, 100);
}

function(container, apiUrl, tables) {
  // チャート描画関数
  function drawPriceComparisonChart() {
    const canvas = container.querySelector('#price-comparison-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // データ
    const products = ['製品A', '製品B', '製品C', '製品D', '製品E'];
    const ourPrices = [12000, 8500, 15000, 9800, 11200];
    const marketPrices = [11500, 9200, 14500, 10500, 10800];

    const maxPrice = Math.max(...ourPrices, ...marketPrices);
    const chartHeight = 180;
    const chartWidth = 320;
    const barWidth = 25;
    const spacing = 50;

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = 40 + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(40 + chartWidth, y);
      ctx.stroke();
    }

    // バー描画
    products.forEach((product, i) => {
      const x = 50 + i * spacing;

      // 当社価格（青）
      const ourHeight = (ourPrices[i] / maxPrice) * chartHeight;
      ctx.fillStyle = '#3b82f6';
      ctx.fillRect(x, 220 - ourHeight, barWidth, ourHeight);

      // 市場価格（オレンジ）
      const marketHeight = (marketPrices[i] / maxPrice) * chartHeight;
      ctx.fillStyle = '#f59e0b';
      ctx.fillRect(x + barWidth + 5, 220 - marketHeight, barWidth, marketHeight);

      // ラベル
      ctx.fillStyle = '#9ca3af';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(product, x + barWidth, 235);
    });

    // 凡例
    ctx.fillStyle = '#3b82f6';
    ctx.fillRect(280, 20, 15, 10);
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('当社価格', 300, 29);

    ctx.fillStyle = '#f59e0b';
    ctx.fillRect(280, 35, 15, 10);
    ctx.fillText('市場価格', 300, 44);
  }

  function drawPurchasePatternChart() {
    const canvas = container.querySelector('#purchase-pattern-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 月別購買データ
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const amounts = [850, 920, 780, 1100, 950, 1050];

    const maxAmount = Math.max(...amounts);
    const chartHeight = 180;
    const chartWidth = 320;

    // グリッド線
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = 40 + (chartHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(40, y);
      ctx.lineTo(40 + chartWidth, y);
      ctx.stroke();
    }

    // 線グラフ
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();

    amounts.forEach((amount, i) => {
      const x = 40 + (chartWidth / (amounts.length - 1)) * i;
      const y = 220 - (amount / maxAmount) * chartHeight;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // ポイント
      ctx.fillStyle = '#10b981';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, Math.PI * 2);
      ctx.fill();
    });

    ctx.stroke();

    // X軸ラベル
    ctx.fillStyle = '#9ca3af';
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    months.forEach((month, i) => {
      const x = 40 + (chartWidth / (months.length - 1)) * i;
      ctx.fillText(month, x, 235);
    });
  }

  // テーブル再描画関数
  function renderPriceTable() {
    const tbody = container.querySelector('#price-tbody');
    const sampleData = [
      { customer: '株式会社テクノロジー', price: 12500, diff: '+8.7%' },
      { customer: 'グローバル商事', price: 9800, diff: '+6.5%' },
      { customer: 'イノベーション工業', price: 11200, diff: '-2.1%' },
      { customer: 'スマートソリューションズ', price: 13800, diff: '+12.3%' }
    ];

    tbody.innerHTML = sampleData.map(row => `
      <tr class="border-b border-solid" style="border-color: rgba(255,255,255,0.1);">
        <td class="py-2 text-xs" style="color: var(--text);">${row.customer}</td>
        <td class="py-2 text-xs text-right" style="color: var(--text);">¥${row.price.toLocaleString()}</td>
        <td class="py-2 text-xs text-right" style="color: ${row.diff.startsWith('+') ? '#4ade80' : '#f87171'};">${row.diff}</td>
      </tr>
    `).join('');
  }

  function renderCompetitorTable() {
    const tbody = container.querySelector('#competitor-tbody');
    const sampleData = [
      { product: '製品A', marketPrice: 11500, ourPrice: 12000 },
      { product: '製品B', marketPrice: 9200, ourPrice: 8500 },
      { product: '製品C', marketPrice: 14500, ourPrice: 15000 },
      { product: '製品D', marketPrice: 10500, ourPrice: 9800 }
    ];

    tbody.innerHTML = sampleData.map(row => `
      <tr class="border-b border-solid" style="border-color: rgba(255,255,255,0.1);">
        <td class="py-2 text-xs" style="color: var(--text);">${row.product}</td>
        <td class="py-2 text-xs text-right" style="color: var(--text);">¥${row.marketPrice.toLocaleString()}</td>
        <td class="py-2 text-xs text-right" style="color: var(--text);">¥${row.ourPrice.toLocaleString()}</td>
      </tr>
    `).join('');
  }

  function renderNegotiationTimeline() {
    const timeline = container.querySelector('#negotiation-timeline');
    const negotiations = tables[0].records || [];

    timeline.innerHTML = negotiations.slice(0, 8).map(nego => {
      const statusColor = nego.交渉ステータス === '合意' ? '#4ade80' : 
                         nego.交渉ステータス === '交渉中' ? '#fbbf24' : '#f87171';

      return `
        <div class="flex items-start gap-3">
          <div class="w-2 h-2 rounded-full mt-2" style="background: ${statusColor};"></div>
          <div class="flex-1">
            <div class="text-xs font-medium" style="color: var(--text);">${nego.顧客名 || '顧客情報なし'}</div>
            <div class="text-xs mt-1" style="color: var(--text-muted);">
              ${nego.現在単価 ? `¥${nego.現在単価.toLocaleString()}` : '価格未設定'} → 
              ${nego.提案単価 ? `¥${nego.提案単価.toLocaleString()}` : '提案なし'}
            </div>
            <div class="text-xs mt-1" style="color: ${statusColor};">${nego.交渉ステータス || '状況不明'}</div>
            <div class="text-xs" style="color: var(--text-muted);">
              ${nego.交渉開始日 ? new Date(nego.交渉開始日).toLocaleDateString() : '日付不明'}
            </div>
          </div>
        </div>
      `;
    }).join('');
  }

  // 初期描画
  setTimeout(() => {
    drawPriceComparisonChart();
    drawPurchasePatternChart();
  }, 100);

  renderPriceTable();
  renderCompetitorTable();
  renderNegotiationTimeline();

  // 分析実行ボタン
  container.querySelector('#btn-analyze').addEventListener('click', async () => {
    const customer = container.querySelector('#customer-filter').value;
    const category = container.querySelector('#category-filter').value;
    const dateFrom = container.querySelector('#date-from').value;
    const dateTo = container.querySelector('#date-to').value;

    // 分析実行（フィルタリング）
    const negotiations = await window.aivicApi.list(0);
    if (negotiations) {
      let filtered = negotiations;

      if (customer) {
        filtered = filtered.filter(n => n.顧客ID === customer);
      }
      if (dateFrom) {
        filtered = filtered.filter(n => new Date(n.交渉開始日) >= new Date(dateFrom));
      }
      if (dateTo) {
        filtered = filtered.filter(n => new Date(n.交渉開始日) <= new Date(dateTo));
      }

      // タイムライン更新
      const timeline = container.querySelector('#negotiation-timeline');
      timeline.innerHTML = filtered.slice(0, 8).map(nego => {
        const statusColor = nego.交渉ステータス === '合意' ? '#4ade80' : 
                           nego.交渉ステータス === '交渉中' ? '#fbbf24' : '#f87171';

        return `
          <div class="flex items-start gap-3">
            <div class="w-2 h-2 rounded-full mt-2" style="background: ${statusColor};"></div>
            <div class="flex-1">
              <div class="text-xs font-medium" style="color: var(--text);">${nego.顧客名 || '顧客情報なし'}</div>
              <div class="text-xs mt-1" style="color: var(--text-muted);">
                ${nego.現在単価 ? `¥${nego.現在単価.toLocaleString()}` : '価格未設定'} → 
                ${nego.提案単価 ? `¥${nego.提案単価.toLocaleString()}` : '提案なし'}
              </div>
              <div class="text-xs mt-1" style="color: ${statusColor};">${nego.交渉ステータス || '状況不明'}</div>
              <div class="text-xs" style="color: var(--text-muted);">
                ${nego.交渉開始日 ? new Date(nego.交渉開始日).toLocaleDateString() : '日付不明'}
              </div>
            </div>
          </div>
        `;
      }).join('');

      // チャート再描画
      drawPriceComparisonChart();
      drawPurchasePatternChart();
    }
  });

  // 価格戦略策定画面への遷移
  container.querySelector('#btn-strategy').addEventListener('click', () => {
    window.showScreen("scr-1780312389834");
  });
}
